import type { ChatIntent } from "@/components/RobotAssistant/chat";
import { serviceFamilies, type ServiceCategory, type ServiceId } from "./services";
import { solutionNavigation } from "./navigation";
import { getPublishedProjects, projects, type ProjectImage } from "./projects";

export type ResourceFormat = "article" | "guide" | "comparison" | "checklist" | "tutorial" | "analysis" | "video" | "case-study";
export type SearchIntent = "informational" | "commercial" | "transactional" | "navigational";
export type FunnelStage = "discovery" | "consideration" | "decision";
export type ResourceAuthor = { name: string; type: "Person" | "Organization"; url: string | null };
export type ResourceVideo = {
  src: string; poster: string; title: string; transcript: string;
  /** Supply only from a documented publication record; otherwise no VideoObject. */
  uploadDate: string | null; duration: string | null; sourceRef: string | null;
};
export type ResourceBlock =
  | { type: "paragraph"; text: string }
  | { type: "heading"; text: string; level?: 2 | 3 }
  | { type: "list"; items: readonly string[] }
  | { type: "links"; label: string; links: readonly { href: string; label: string }[] }
  | { type: "table"; caption: string; headers: readonly string[]; rows: readonly (readonly string[])[] };
export type ResourceCta =
  | { type: "solution"; family: ServiceCategory; label: string }
  | { type: "project"; projectId: string; label: string }
  | { type: "audit"; service: ServiceId; label: string }
  | { type: "explain-project" | "contact"; label: string }
  | { type: "chat"; intent: ChatIntent; label: string };

export type Resource = {
  id: string; slug: string; title: string; description: string;
  format: ResourceFormat; status: "draft" | "published";
  publishedAt: string | null; updatedAt: string | null; author: ResourceAuthor | null;
  topic: ServiceCategory; serviceFamilies: readonly ServiceCategory[];
  relatedServices: readonly ServiceId[]; relatedProjects: readonly string[];
  relatedResources: readonly string[]; keywords: readonly string[];
  searchIntent: SearchIntent; funnelStage: FunnelStage; featured: boolean;
  coverImage: ProjectImage | null; video: ResourceVideo | null; readingTime: number | null;
  seoTitle: string | null; seoDescription: string | null; canonical: string;
  indexable: boolean; content: readonly ResourceBlock[] | null;
  cta: ResourceCta; sourceRefs: readonly string[];
};

/** The clusters reuse the commercial families, without a competing taxonomy. */
export const resourceClusters = serviceFamilies.map(family => ({ id: family.id, name: family.name }));
const origin = "https://www.code-v.fr";

function draft(data: Pick<Resource, "id" | "slug" | "title" | "description" | "format" | "topic" | "relatedServices" | "relatedProjects" | "relatedResources" | "keywords" | "searchIntent" | "funnelStage" | "cta">): Resource {
  return { ...data, status: "draft", publishedAt: null, updatedAt: null, author: null,
    serviceFamilies: [data.topic], featured: false, coverImage: null, video: null,
    readingTime: null, seoTitle: null, seoDescription: null,
    canonical: `${origin}/ressources/${data.slug}`, indexable: false, content: null, sourceRefs: [],
  };
}

/** Publication recorded on 4 October 2026 (Europe/Paris). Organization is the editor. */
function article(data: Pick<Resource, "id" | "slug" | "title" | "description" | "topic" | "relatedServices" | "relatedResources" | "keywords" | "cta" | "sourceRefs"> & { content: readonly ResourceBlock[]; serviceFamilies?: readonly ServiceCategory[]; featured?: boolean; searchIntent?: SearchIntent; publishedAt?: string }): Resource {
  const words = data.content.map(block => block.type === "list" ? block.items.join(" ") : block.type === "table" ? [block.caption, ...block.headers, ...block.rows.flat()].join(" ") : block.type === "links" ? [block.label, ...block.links.map(link => link.label)].join(" ") : block.text).join(" ").split(/\s+/).length;
  return { ...data, format: "article", status: "published", publishedAt: data.publishedAt ?? "2026-10-03T23:08:59Z", updatedAt: null,
    author: { name: "CODE-V", type: "Organization", url: origin }, serviceFamilies: data.serviceFamilies ?? [data.topic],
    relatedProjects: [], searchIntent: data.searchIntent ?? "commercial", funnelStage: "consideration", featured: data.featured ?? false,
    coverImage: null, video: null, readingTime: Math.max(1, Math.ceil(words / 200)),
    seoTitle: `${data.title} | CODE-V`, seoDescription: data.description, canonical: `${origin}/ressources/${data.slug}`, indexable: true,
  };
}

/** Published articles and retained internal editorial briefs share one registry. */
export const resources: readonly Resource[] = [
  article({ id: "gbp-optimization", slug: "optimiser-fiche-google-business-profile", publishedAt: "2026-10-03T23:26:19Z", title: "Google Business Profile : comment optimiser sa fiche efficacement", description: "Catégories, services, photos et avis : organisez les améliorations de votre fiche Google pour représenter votre activité et faciliter la prise de contact.", topic: "seo", searchIntent: "informational", relatedServices: ["local-seo", "gbp-management"], relatedResources: ["local-google-visibility", "local-services-guide"], keywords: ["optimiser fiche Google Business Profile", "catégories fiche Google", "optimisation GBP"], cta: { type: "contact", label: "Parler de votre fiche Google" }, sourceRefs: ["https://support.google.com/business/answer/3038177?hl=fr", "https://support.google.com/business/answer/7342169?hl=fr", "https://support.google.com/contributionpolicy/answer/7400114?hl=fr"], content: [
    { type: "paragraph", text: "Optimiser une fiche Google commence par représenter correctement votre établissement. Avant de publier davantage, vérifiez que le service recherché, les horaires et le contact sont compréhensibles. Travaillez ensuite par ordre : identité et accès, offre, visuels, relation avec les clients, puis suivi. Une fiche bien renseignée reste un complément de votre site, pas son remplacement." },
    { type: "heading", text: "1. Stabiliser les informations et les accès" },
    { type: "paragraph", text: "Identifiez la personne qui détient la fiche et les collaborateurs autorisés à la gérer. Assurez-vous que l’accès ne dépend pas uniquement d’un ancien prestataire. Vérifiez le nom réel, le téléphone et le lien vers le site. Pour l’adresse et la zone desservie, suivez les consignes Google correspondant à votre mode d’accueil. Ne créez pas une seconde fiche pour contourner un problème d’accès." },
    { type: "heading", text: "2. Choisir les catégories et décrire l’offre" },
    { type: "paragraph", text: "La catégorie principale doit correspondre à l’activité centrale. Les catégories complémentaires ne doivent pas former un inventaire de tous les métiers voisins. Dans les services, utilisez des intitulés que vos clients comprennent et ajoutez les précisions réellement utiles. Une prestation que vous ne proposez pas attire des demandes inutiles, même si son intitulé paraît intéressant." },
    { type: "heading", level: 3, text: "Une description qui aide à choisir" },
    { type: "paragraph", text: "Présentez votre activité, le public concerné et ce qui distingue votre façon de travailler. Évitez une liste répétée de villes et de mots-clés. Les consignes Google encadrent les descriptions, notamment les liens et contenus promotionnels. Les coordonnées et horaires disposent de leurs propres champs : inutile de tout répéter dans le texte." },
    { type: "heading", text: "3. Préparer des photos et publications utiles" },
    { type: "paragraph", text: "Choisissez des images actuelles : entrée des locaux si vous accueillez, espace de travail, équipe avec son accord ou réalisations pertinentes. Une photo doit aider à reconnaître l’entreprise ou à comprendre le service. Les publications peuvent présenter une actualité concrète et une prochaine action. Vérifiez les fonctions disponibles dans votre fiche et relisez le lien avant de publier." },
    { type: "paragraph", text: "Exemple : pour annoncer des horaires exceptionnels, actualisez d’abord les horaires concernés. Une publication peut ensuite expliquer le contexte. Publier une image avec la bonne information ne corrige pas un champ d’horaires resté faux. Le même principe s’applique au téléphone et aux services." },
    { type: "heading", text: "4. Organiser les avis sans les orienter" },
    { type: "paragraph", text: "Demandez un retour sincère après une prestation et facilitez l’accès à la fiche. Les règles Google interdisent les contreparties proposées en échange d’un avis. Répondez aux retours avec des informations utiles, sans divulguer de données personnelles. Si un problème exige des détails, proposez de poursuivre en privé plutôt que d’exposer un dossier client." },
    { type: "heading", text: "5. Vérifier la cohérence avec le site" },
    { type: "list", items: ["Même activité et mêmes coordonnées sur la fiche et le site.", "Pages qui expliquent les prestations réellement proposées.", "Zone d’intervention précise, sans multiplication artificielle des établissements.", "Contact mobile testé et demandes effectivement reçues.", "Responsable identifié pour les horaires, photos et réponses."] },
    { type: "paragraph", text: "Conservez un petit journal des modifications et examinez les interactions disponibles dans votre fiche. Rapprochez-les des demandes reçues : sujet, zone et qualité du contact. Si les visiteurs cliquent mais arrivent sur une page trop vague, améliorez cette page avant d’ajouter des publications. L’optimisation devient ainsi un entretien ciblé plutôt qu’une série de tâches sans objectif." },
    { type: "links", label: "Les prochaines étapes", links: [{ href: "/referencement-local", label: "Préparer l’optimisation de votre présence locale" }, { href: "/ressources/visibilite-locale-google", label: "Comprendre les leviers de visibilité locale" }, { href: "/realisations", label: "Voir des présentations web d’activités locales" }, { href: "https://support.google.com/business/answer/3038177?hl=fr", label: "Google : représenter correctement votre établissement" }, { href: "https://support.google.com/business/answer/7342169?hl=fr", label: "Google : créer et gérer des publications" }, { href: "https://support.google.com/contributionpolicy/answer/7400114?hl=fr", label: "Google : règles relatives aux avis" }] },
  ] }),
  article({ id: "ads-budget", slug: "budget-google-ads-demarrer", publishedAt: "2026-10-03T23:26:19Z", title: "Google Ads : quel budget prévoir pour démarrer ?", description: "Construisez une enveloppe de test Google Ads à partir de votre offre, de votre zone et des demandes recherchées, puis apprenez à lire les premiers résultats.", topic: "acquisition", relatedServices: ["google-ads"], relatedResources: ["seo-or-ads", "local-services-guide"], keywords: ["budget Google Ads démarrer", "budget publicité Google", "coût campagne Search"], cta: { type: "contact", label: "Cadrer votre budget publicitaire" }, sourceRefs: ["https://support.google.com/google-ads/answer/6385083?hl=fr", "https://support.google.com/google-ads/answer/1722122?hl=fr"], content: [
    { type: "paragraph", text: "Il n’existe pas de budget de départ valable pour toutes les entreprises. L’enveloppe dépend de la demande, de la concurrence, de la zone et de votre capacité à transformer un contact en client. Pour démarrer, choisissez une offre précise et une question à tester. Une campagne qui doit tout promouvoir à la fois disperse les moyens et rend les enseignements difficiles à interpréter." },
    { type: "heading", text: "Séparer diffusion, préparation et suivi" },
    { type: "paragraph", text: "Le budget versé à Google finance la diffusion. La création de la campagne, la page d’arrivée, le suivi des conversions et la gestion constituent d’autres postes. Demandez une estimation qui les distingue. Si une page doit être créée ou un formulaire réparé, prévoyez ce travail avant le lancement : payer des visites sur un parcours qui échoue ne permet pas un test utile." },
    { type: "heading", text: "Partir du marché et de votre économie" },
    { type: "heading", level: 3, text: "Le coût par clic est une estimation, pas une promesse" },
    { type: "paragraph", text: "Les estimations disponibles dans les outils Google servent à préparer des scénarios. Le coût réel varie selon les enchères, les recherches et les conditions de diffusion. Il ne suffit pas de multiplier un CPC estimé par un nombre de clics pour prévoir les clients obtenus. Une recherche très proche de l’achat peut coûter davantage tout en produisant des contacts plus pertinents." },
    { type: "heading", level: 3, text: "La zone et l’offre limitent le périmètre" },
    { type: "paragraph", text: "Choisissez les services et territoires que vous pouvez réellement prendre en charge. Écartez les recherches manifestement hors sujet et vérifiez régulièrement les termes qui déclenchent les annonces. Une entreprise locale avec peu de capacité disponible n’a pas le même besoin qu’un prestataire national. Votre premier budget doit rester supportable même si le test n’aboutit pas." },
    { type: "heading", text: "Définir une enveloppe et des règles de décision" },
    { type: "list", items: ["Une offre et une zone clairement délimitées.", "Une enveloppe de diffusion que l’entreprise peut consacrer au test.", "Des actions suivies : formulaire reçu, appel et qualification commerciale.", "Une personne chargée de traiter les demandes et de noter leur pertinence.", "Des critères de pause ou de correction si les recherches et contacts sont hors cible."] },
    { type: "paragraph", text: "Google utilise notamment des budgets quotidiens moyens. Pour la plupart des campagnes, la documentation indique des limites de dépense quotidienne et mensuelle qui ne correspondent pas à un plafond strict identique chaque jour. Vérifiez les règles de votre type de campagne et les réglages de facturation avant lancement. Ne confondez pas enveloppe décidée en interne et fonctionnement de la plateforme." },
    { type: "heading", text: "Lire les premières données sans conclure trop vite" },
    { type: "paragraph", text: "Contrôlez d’abord la diffusion et les recherches touchées, puis les contacts réellement reçus. Si des clics existent sans demandes, testez la page et le suivi. Si les demandes sont hors zone, corrigez le ciblage. Si elles sont pertinentes mais ne deviennent pas des clients, examinez aussi l’offre, les échanges et la capacité à répondre. L’absence de conversion ne désigne pas automatiquement un seul responsable." },
    { type: "paragraph", text: "Calculez le coût des demandes qualifiées à partir des données réelles et distinguez les frais de diffusion des frais de gestion. Comparez ce coût avec votre marge et votre transformation commerciale. Une petite quantité de contacts ne permet pas une prévision robuste ; gardez plusieurs explications possibles tant que les données sont limitées." },
    { type: "heading", text: "Les erreurs qui rendent un test peu utile" },
    { type: "paragraph", text: "Évitez de lancer trop d’offres avec une enveloppe réduite, de suivre uniquement les clics, de changer tous les paramètres en même temps ou d’augmenter la dépense avant de corriger les demandes hors cible. Un test doit aboutir à une décision : continuer sur ce périmètre, corriger le parcours, ou étudier un autre levier." },
    { type: "links", label: "Préparer une campagne", links: [{ href: "/publicite", label: "Cadrer vos campagnes avec CODE-V" }, { href: "/ressources/seo-ou-google-ads-prospects", label: "Comparer SEO et Google Ads" }, { href: "/strategie-digitale", label: "Prioriser vos leviers d’acquisition" }, { href: "/realisations", label: "Observer des parcours web réalisés" }, { href: "https://support.google.com/google-ads/answer/6385083?hl=fr", label: "Google : fonctionnement des budgets quotidiens moyens" }] },
  ] }),
  article({ id: "local-services-guide", slug: "google-local-services-ads-fonctionnement", publishedAt: "2026-10-03T23:26:19Z", title: "Google Local Services Ads : comment ça fonctionne ?", description: "Comprenez les annonces Local Services : éligibilité, contact direct, facturation des prospects et différences avec une campagne Google Ads classique.", topic: "acquisition", relatedServices: ["local-services", "google-ads"], relatedResources: ["ads-budget", "gbp-optimization"], keywords: ["Google Local Services Ads fonctionnement", "LSA France", "annonces services locaux"], cta: { type: "contact", label: "Étudier Local Services pour votre activité" }, sourceRefs: ["https://support.google.com/localservices/answer/6224841?co=GENIE.CountryCode%3DFR&hl=fr", "https://support.google.com/localservices/answer/7195435?hl=fr"], content: [
    { type: "paragraph", text: "Local Services est un dispositif publicitaire destiné à certaines activités de services locaux. Le parcours repose sur un profil et un contact direct, plutôt que sur la seule visite d’une page d’arrivée. Avant de comparer des budgets, vérifiez si votre activité et votre zone peuvent y accéder. Une disponibilité générale en France ne signifie pas que toute entreprise est éligible." },
    { type: "heading", text: "Vérifier l’éligibilité avant de prévoir la campagne" },
    { type: "paragraph", text: "Google propose un outil de vérification fondé sur le service et la localisation. Les catégories, les conditions et les contrôles peuvent évoluer. Utilisez les informations actuelles de votre compte plutôt qu’une liste ancienne de métiers. Les justificatifs requis et les étapes de validation dépendent de votre activité ; rassemblez les documents demandés avant d’annoncer une date de lancement." },
    { type: "heading", text: "Du profil au contact" },
    { type: "paragraph", text: "Dans les zones et catégories couvertes, une personne peut trouver votre profil puis vous contacter via les possibilités proposées. Les fonctions disponibles varient selon le pays et le secteur. Le profil doit représenter vos prestations réelles et votre capacité à les traiter. Surveillez les demandes dans l’interface concernée et organisez leur prise en charge." },
    { type: "paragraph", text: "Le premier travail commercial reste le même : comprendre la demande, vérifier la zone, qualifier l’intervention et proposer la suite. Un contact facturé n’est pas une vente. Les horaires, la disponibilité de l’équipe et la capacité à rappeler comptent dans votre organisation, indépendamment de la performance publicitaire." },
    { type: "heading", text: "Une logique de facturation différente" },
    { type: "paragraph", text: "Google décrit une facturation des prospects valides, avec un budget hebdomadaire moyen et une limite mensuelle. Les conditions et possibilités de gestion des prospects doivent être vérifiées dans votre compte. Ne transposez pas automatiquement le coût par clic d’une campagne Search au coût d’un prospect Local Services." },
    { type: "paragraph", text: "Votre analyse doit distinguer les contacts facturés, ceux qui répondent à votre périmètre et les missions finalement réalisées. Notez les motifs de refus utiles : zone, prestation ou disponibilité. Ce suivi permet de décider si le dispositif convient à l’activité et si votre profil doit être ajusté." },
    { type: "heading", text: "Local Services ou Search : les questions à comparer" },
    { type: "table", caption: "Comparer les dispositifs avant de choisir", headers: ["Question", "Local Services", "Google Ads Search"], rows: [["Accès", "Catégorie et zone à vérifier", "Choix de campagne et règles publicitaires"], ["Parcours", "Profil et contact direct selon les fonctions disponibles", "Annonce et page d’arrivée"], ["Lecture du coût", "Prospects facturés puis qualifiés", "Diffusion et conversions suivies"], ["Préparation", "Profil, documents et traitement des contacts", "Ciblage, annonces, page et tracking"]] },
    { type: "heading", text: "Quand l’étudier, et quand attendre" },
    { type: "paragraph", text: "Le dispositif mérite une étude si l’éligibilité est confirmée, si vos prestations sont précisément définies et si votre équipe peut répondre aux demandes. Si le traitement des contacts est déjà désorganisé, préparez ce fonctionnement avant de chercher davantage de sollicitations. Une entreprise dont la catégorie n’est pas proposée doit examiner d’autres leviers plutôt que modifier artificiellement son activité déclarée." },
    { type: "list", items: ["Vérifier métier et zone dans l’outil officiel.", "Identifier les documents et contrôles requis.", "Définir les prestations acceptées et la personne responsable des contacts.", "Lire les modalités de budget et facturation applicables.", "Suivre la pertinence des demandes et les missions réalisées avant d’élargir."] },
    { type: "links", label: "Cadrer l’acquisition locale", links: [{ href: "/publicite", label: "Comparer les options publicitaires avec CODE-V" }, { href: "/ressources/budget-google-ads-demarrer", label: "Préparer le budget d’une campagne Google Ads" }, { href: "/referencement-local", label: "Travailler aussi votre présence locale naturelle" }, { href: "/realisations", label: "Découvrir les réalisations CODE-V" }, { href: "https://support.google.com/localservices/answer/6224841?co=GENIE.CountryCode%3DFR&hl=fr", label: "Google : démarrer Local Services en France" }, { href: "https://support.google.com/localservices/answer/7195435?hl=fr", label: "Google : fonctionnement des prospects et de leur facturation" }] },
  ] }),
  article({ id: "showcase-or-ecommerce", slug: "site-vitrine-ou-ecommerce-choisir", publishedAt: "2026-10-03T23:26:19Z", title: "Site vitrine ou site e-commerce : comment choisir ?", description: "Présentation, catalogue ou vente en ligne : choisissez le site adapté à votre parcours client et aux moyens disponibles pour gérer commandes et contenus.", topic: "web", relatedServices: ["website"], relatedResources: ["website-cost-2026", "website-redesign"], keywords: ["site vitrine ou e-commerce", "catalogue ou boutique en ligne", "choisir type site entreprise"], cta: { type: "contact", label: "Choisir le site adapté à votre activité" }, sourceRefs: ["https://www.economie.gouv.fr/entreprises/developper-son-entreprise/innover-et-numeriser-son-entreprise/creer-votre-boutique-en-ligne-mode-demploi"], content: [
    { type: "paragraph", text: "La différence décisive n’est pas le nombre de produits affichés. Un site vitrine présente une activité et facilite une prise de contact. Une boutique permet de conclure un achat en ligne. Entre les deux, un catalogue peut aider à choisir avant un devis ou une commande traitée autrement. Choisissez selon votre vente réelle, puis selon votre capacité à faire fonctionner le parcours." },
    { type: "heading", text: "Quand un site vitrine répond au besoin" },
    { type: "paragraph", text: "Si chaque prestation demande un échange, une visite ou une estimation particulière, un bon site vitrine peut être suffisant. Il décrit les services, répond aux questions courantes et permet de transmettre les bons éléments. Le formulaire doit recueillir ce qui aide la qualification sans décourager le contact. Afficher un bouton d’achat ne simplifie pas une prestation qui reste à définir." },
    { type: "heading", text: "Le catalogue : présenter sans vendre automatiquement" },
    { type: "paragraph", text: "Un catalogue convient lorsque les visiteurs doivent explorer une gamme, mais que le prix, la disponibilité ou la livraison se confirment ensuite. Présentez clairement la prochaine étape : demande de renseignements, devis ou visite. Évitez un parcours qui ressemble à une boutique sans expliquer pourquoi le client ne peut pas commander." },
    { type: "heading", text: "Ce qu’une boutique ajoute à votre organisation" },
    { type: "table", caption: "Les responsabilités à prévoir pour la vente en ligne", headers: ["Sujet", "Question opérationnelle"], rows: [["Produits", "Qui tient les fiches, variantes et disponibilités à jour ?"], ["Paiement", "Comment sont traités paiement, échec et remboursement ?"], ["Commande", "Qui contrôle et prépare les commandes reçues ?"], ["Livraison", "Quels modes, coûts et restrictions sont applicables ?"], ["Après-vente", "Qui répond aux demandes et gère les retours ?"]] },
    { type: "paragraph", text: "La vente en ligne implique aussi des informations et conditions adaptées au commerce concerné. Le guide du ministère de l’Économie constitue un point de départ pour repérer les sujets à traiter. Faites vérifier les conditions qui s’appliquent à votre activité avant le lancement, notamment lorsque les ventes ou produits présentent des particularités." },
    { type: "heading", level: 3, text: "Les coûts indirects comptent dans la décision" },
    { type: "paragraph", text: "La création n’est qu’un poste : préparation des fiches, photographies, traitement des commandes, service client, licences, commissions et entretien doivent entrer dans votre calcul. Une boutique peu coûteuse à mettre en ligne peut demander beaucoup de temps à exploiter. Vérifiez également comment les données du stock et de la facturation seront échangées avec vos outils." },
    { type: "heading", text: "Trois scénarios pour éclairer le choix" },
    { type: "list", items: ["Un artisan établit son devis après visite : présentation de services et demande qualifiée avant paiement en ligne.", "Un distributeur vend une gamme dont les conditions dépendent du projet : catalogue avec demande de proposition.", "Une marque vend des produits standardisés et dispose d’une organisation de préparation : boutique avec parcours d’achat complet."] },
    { type: "paragraph", text: "Ces scénarios aident à poser les bonnes questions, mais la décision dépend de vos ventes. Interrogez vos clients : quelles informations leur manquent, souhaitent-ils commander seuls et quels points nécessitent encore un échange ? Une contrainte commerciale ne se résout pas toujours par une fonctionnalité." },
    { type: "heading", text: "Préparer une évolution sans la présumer simple" },
    { type: "paragraph", text: "Vous pouvez commencer par une présentation ou un catalogue si cela répond au besoin actuel. Si une boutique est envisagée ensuite, signalez-le dans le brief : structure des produits, choix techniques et outils peuvent en dépendre. Ajouter un paiement plus tard ne consiste pas seulement à activer un bouton ; le traitement des commandes doit aussi être prêt." },
    { type: "paragraph", text: "Avant de décider, décrivez votre parcours depuis la découverte jusqu’à la livraison ou la réalisation. Notez où intervient votre équipe et quelles étapes peuvent être autonomes. Cette carte permet de choisir une première version cohérente, avec des fonctions réellement utilisées plutôt qu’une boutique ajoutée par principe." },
    { type: "links", label: "Préparer le bon périmètre", links: [{ href: "/creation-site", label: "Cadrer votre site avec CODE-V" }, { href: "/ressources/prix-site-internet-professionnel-2026", label: "Préparer le budget de votre site" }, { href: "/maintenance-site", label: "Prévoir l’entretien après mise en ligne" }, { href: "/realisations", label: "Observer différents sites d’entreprise" }, { href: "https://www.economie.gouv.fr/entreprises/developper-son-entreprise/innover-et-numeriser-son-entreprise/creer-votre-boutique-en-ligne-mode-demploi", label: "Ministère de l’Économie : créer une boutique en ligne" }] },
  ] }),
  article({ id: "redesign-for-seo", slug: "refaire-site-ameliorer-seo", publishedAt: "2026-10-03T23:26:19Z", title: "Faut-il refaire son site pour améliorer son SEO ?", description: "Identifiez les problèmes SEO qui se corrigent sur un site existant et ceux qui justifient une refonte, puis préparez les précautions d’une migration.", topic: "seo", serviceFamilies: ["web", "seo"], relatedServices: ["website", "seo"], relatedResources: ["website-redesign", "seo-or-ads"], keywords: ["refaire site améliorer SEO", "refonte référencement naturel", "migration site SEO"], cta: { type: "contact", label: "Évaluer votre site et ses priorités SEO" }, sourceRefs: ["https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=fr", "https://developers.google.com/search/docs/crawling-indexing/site-move-with-url-changes?hl=fr"], content: [
    { type: "paragraph", text: "Une visibilité insuffisante ne signifie pas automatiquement qu’il faut reconstruire le site. Des pages manquantes, des contenus imprécis ou un réglage d’indexation peuvent se traiter sur l’existant. Une refonte devient pertinente quand la structure ou la technique empêche durablement ces améliorations. Le diagnostic doit séparer ce qui manque de ce qui bloque réellement." },
    { type: "heading", text: "Commencer par les problèmes observables" },
    { type: "paragraph", text: "Vérifiez si les pages utiles sont accessibles, indexables et reliées par la navigation. Examinez leur contenu : répond-il aux services recherchés et aux questions des clients ? Lorsque Search Console est disponible, consultez les pages et requêtes concernées plutôt qu’un seul total. Une absence de clics peut venir d’une page nouvelle, d’un sujet mal couvert ou d’autres causes qu’un mauvais design." },
    { type: "heading", text: "Quand améliorer l’existant suffit" },
    { type: "list", items: ["Les contenus peuvent être modifiés et de nouvelles pages ajoutées proprement.", "Les réglages qui empêchent l’indexation peuvent être corrigés.", "Les liens internes et la navigation peuvent être améliorés.", "Les médias et ressources responsables des lenteurs peuvent être optimisés.", "Les parcours restent utilisables et la base technique peut être entretenue."] },
    { type: "paragraph", text: "Dans ce cas, commencez par une priorité mesurable : clarifier une prestation, rendre une page découvrable ou corriger un problème précis. Une nouvelle apparence seule ne constitue pas une stratégie de contenu. Si le site décrit mal l’activité, reprendre ses textes reste nécessaire même après une reconstruction." },
    { type: "heading", text: "Quand une refonte mérite d’être étudiée" },
    { type: "paragraph", text: "Une refonte peut se justifier lorsque l’architecture ne correspond plus à l’offre, lorsque les modèles de pages rendent les contenus utiles impossibles à présenter ou lorsque les corrections s’accumulent sur une base difficile à maintenir. Comparez le coût et le risque d’une série de réparations avec ceux d’une reconstruction cadrée. Le simple âge du site ne permet pas cet arbitrage." },
    { type: "heading", level: 3, text: "La performance est un sujet précis" },
    { type: "paragraph", text: "Une image lourde peut se corriger sans refonte. Une chaîne de composants ou de services qui ralentit tous les parcours peut demander un travail plus profond. Mesurez les pages et usages concernés, puis cherchez les causes. Changer de technologie sans diagnostic ne garantit pas une amélioration ni une progression dans la recherche." },
    { type: "heading", text: "Préserver les acquis pendant une migration" },
    { type: "paragraph", text: "Inventoriez les anciennes URLs, leur contenu et leur destination future. Si les chemins changent, préparez des redirections permanentes vers les pages correspondantes. Vérifiez les liens internes, les canonical, l’indexation et le sitemap. Google rappelle qu’un changement d’URLs demande un traitement et peut s’accompagner de fluctuations : le lancement mérite un suivi, pas seulement une nouvelle page d’accueil." },
    { type: "table", caption: "Les contrôles à organiser autour de la mise en ligne", headers: ["Avant", "Après"], rows: [["Inventaire des URLs et contenus utiles", "Vérification des réponses et redirections"], ["Plan des nouvelles pages et liens", "Contrôle des parcours et liens internes"], ["Réglages d’indexation prévus", "Inspection des pages et suivi Search Console"], ["Tests du contact et de la mesure", "Vérification des demandes et événements reçus"]] },
    { type: "heading", text: "Ne pas confondre refonte et acquisition" },
    { type: "paragraph", text: "Exemple : un site présente une seule page pour plusieurs services distincts. Ajouter des pages utiles et des liens peut résoudre une partie du problème sans tout remplacer. Si le système empêche cette organisation, une refonte devient une option. Dans les deux cas, le travail éditorial et le suivi restent nécessaires ; la mise en ligne ne crée pas à elle seule une demande commerciale." },
    { type: "paragraph", text: "Demandez un diagnostic qui distingue les corrections immédiates, les améliorations possibles et les limites structurelles. Faites aussi préciser les pages à conserver, les responsabilités de migration et les critères de réception. Vous pourrez alors choisir une intervention proportionnée plutôt que financer une reconstruction sur une intuition." },
    { type: "links", label: "Décider avant de reconstruire", links: [{ href: "/creation-site", label: "Cadrer une refonte de site" }, { href: "/referencement", label: "Examiner les priorités de référencement" }, { href: "/ressources/refonte-site-internet-quand", label: "Les autres signes qui justifient une refonte" }, { href: "/realisations", label: "Voir les sites réalisés par CODE-V" }, { href: "https://developers.google.com/search/docs/crawling-indexing/site-move-with-url-changes?hl=fr", label: "Google : préparer une migration avec changement d’URLs" }] },
  ] }),
  article({ id: "useful-ai-agents", slug: "agent-ia-entreprise-usages-utiles", publishedAt: "2026-10-03T23:26:19Z", title: "Agent IA pour entreprise : quels usages sont vraiment utiles ?", description: "Qualification, support et recherche interne : choisissez un usage pertinent pour un agent IA et définissez ses sources, permissions et contrôles humains.", topic: "automation", relatedServices: ["ai-agents", "business-workflows"], relatedResources: ["first-automations"], keywords: ["agent IA entreprise usages", "assistant IA métier", "agent IA ou automatisation"], cta: { type: "contact", label: "Cadrer un usage IA utile à votre équipe" }, sourceRefs: ["https://www.cnil.fr/fr/les-questions-reponses-de-la-cnil-sur-lutilisation-dun-systeme-dia-generative", "https://www.cnil.fr/fr/utiliser-lia-generative-dans-les-tpe-et-pme"], content: [
    { type: "paragraph", text: "Un agent IA n’est utile que si son rôle est précis. Il peut préparer une réponse, rechercher une information ou participer à un flux, avec des capacités variables selon le système. Avant d’envisager son autonomie, choisissez une tâche, les sources autorisées et la personne qui valide le résultat. Une démonstration séduisante ne remplace pas un test sur vos usages." },
    { type: "heading", text: "Des usages à cadrer, pas une autonomie générale" },
    { type: "table", caption: "Les usages et leurs points de contrôle", headers: ["Usage", "Aide possible", "Contrôle utile"], rows: [["Qualification", "Préparer les informations d’une demande", "Validation des critères et exceptions"], ["Support", "Proposer une réponse à partir de documents", "Sources à jour et passage à un humain"], ["Synthèse", "Résumer un dossier ou un échange", "Vérification des faits et éléments omis"], ["Reporting", "Commenter des données préparées", "Calculs contrôlés hors du texte généré"], ["Recherche interne", "Retrouver une information documentaire", "Droits d’accès et référence à la source"], ["Flux métier", "Préparer ou déclencher une étape autorisée", "Permissions limitées et actions validées"]] },
    { type: "heading", text: "Commencer par un usage qui prépare le travail" },
    { type: "paragraph", text: "Un assistant qui propose un brouillon de réponse est plus simple à superviser qu’un système qui engage l’entreprise. Pour un support interne, commencez par un ensemble de documents maîtrisés, avec leur propriétaire et leur date de mise à jour. Demandez une référence à la source et un comportement prévu lorsque l’information manque." },
    { type: "paragraph", text: "Exemple : l’équipe cherche une procédure dans plusieurs documents. Un assistant peut retrouver un passage et proposer une synthèse. Il doit conserver les droits de lecture existants et orienter vers le document original. S’il ne trouve pas la réponse, mieux vaut demander une précision ou transmettre la question que produire une procédure plausible mais incorrecte." },
    { type: "heading", text: "Distinguer raisonnement généré et règles explicites" },
    { type: "paragraph", text: "Si une étape suit une règle stable, une automatisation classique peut suffire. Créer un dossier à réception d’un formulaire complet ou envoyer une notification ne demande pas nécessairement un agent. L’IA devient plus intéressante face à des contenus variés, mais ajoute des erreurs possibles et un besoin de vérification. Choisissez la solution la plus simple qui répond au problème." },
    { type: "heading", level: 3, text: "Les calculs et décisions doivent rester vérifiables" },
    { type: "paragraph", text: "Pour un reporting, préparez les chiffres avec des règles déterministes et contrôlez les données sources. L’assistant peut aider à les expliquer, sans inventer les valeurs manquantes. Pour une qualification, conservez une définition explicite des critères et un chemin humain pour les cas ambigus. Le texte produit ne doit pas devenir l’unique preuve d’une décision." },
    { type: "heading", text: "Limiter les accès et les actions" },
    { type: "paragraph", text: "Décidez quelles données peuvent être transmises et quelles personnes peuvent accéder au résultat. Examinez les conditions du fournisseur, la conservation et les possibilités de réutilisation des données. La CNIL recommande d’encadrer les usages et de protéger les informations personnelles et confidentielles. Une connexion à un outil métier ne doit pas donner par défaut tous les droits de l’utilisateur." },
    { type: "list", items: ["Limiter les sources et les permissions au besoin réel.", "Séparer consultation, préparation et action engageante.", "Prévoir une validation avant envoi client ou modification sensible.", "Tracer les actions et permettre l’arrêt du flux.", "Tester les demandes hors périmètre et les instructions présentes dans des documents non fiables.", "Identifier le responsable de la mise à jour et du suivi."] },
    { type: "heading", text: "Quand un agent est inutile" },
    { type: "paragraph", text: "Si le volume est faible, si la procédure est encore indécise ou si les documents se contredisent, commencez par organiser le travail. Un agent ne résout pas automatiquement un manque de règles ou de responsables. Comparez également le temps de supervision et le coût de fonctionnement avec l’aide réellement apportée." },
    { type: "paragraph", text: "Testez sur des cas représentatifs, y compris ceux qui doivent être refusés ou transmis à un humain. Évaluez la justesse, les omissions, la reprise manuelle et la compréhension par l’équipe. Le prochain élargissement doit découler de ces observations, pas du seul fait que le premier scénario fonctionne." },
    { type: "links", label: "Définir un premier usage", links: [{ href: "/solutions/automatisation-ia", label: "Étudier l’automatisation et l’IA avec CODE-V" }, { href: "/ressources/taches-automatiser-petite-entreprise", label: "Choisir les premières tâches à automatiser" }, { href: "/strategie-digitale", label: "Prioriser les projets digitaux" }, { href: "/realisations", label: "Voir les productions CODE-V" }, { href: "https://www.cnil.fr/fr/les-questions-reponses-de-la-cnil-sur-lutilisation-dun-systeme-dia-generative", label: "CNIL : les questions à poser avant d’utiliser une IA générative" }] },
  ] }),
  article({ id: "website-cost-2026", slug: "prix-site-internet-professionnel-2026", title: "Combien coûte un site internet professionnel en 2026 ?", description: "Comprenez les postes de dépense d’un site professionnel, comparez les devis et préparez un budget qui inclut la création, les contenus et l’entretien.", topic: "web", relatedServices: ["website"], relatedResources: ["website-redesign", "seo-or-ads"], keywords: ["prix site internet professionnel 2026", "coût création site web", "budget site vitrine", "devis site internet"], featured: true, cta: { type: "contact", label: "Parler de votre projet" }, sourceRefs: ["https://www.francenum.gouv.fr/guides-et-conseils/developpement-commercial/site-web/combien-payer-pour-un-site-web-ou-un-site-e"], content: [
    { type: "paragraph", text: "Le prix d’un site dépend d’abord de ce qu’il doit permettre de faire. Présenter une activité avec un formulaire, vendre des produits et gérer un espace client demandent des travaux différents. Pour préparer votre budget en 2026, séparez trois enveloppes : la réalisation initiale, les dépenses récurrentes et le travail de votre équipe. Un devis intéressant doit rendre ces trois dimensions lisibles." },
    { type: "heading", text: "Des repères de prix, à replacer dans leur contexte" },
    { type: "paragraph", text: "France Num, dans un dossier mis à jour en juin 2025, rapporte des estimations de professionnels : 500 à 2 000 € pour une seule page, 900 à 5 000 € pour un site basique et 3 000 à 10 000 € pour un e-commerce. Ces fourchettes sont des repères issus de ce dossier, pas une grille de prix 2026 ni un tarif CODE-V. Leur périmètre et leur traitement fiscal doivent être vérifiés dans chaque devis. Un projet spécifique peut se situer hors de ces intervalles." },
    { type: "paragraph", text: "Une enveloppe modeste peut convenir à une présence simple si les textes, les photos et l’identité sont prêts. Elle répond moins bien à un besoin de conception originale, de rédaction complète ou de connexion à plusieurs outils. Demandez ce qui est réellement livré avant de comparer les totaux." },
    { type: "links", label: "Le repère chiffré utilisé", links: [{ label: "France Num : combien payer pour un site web ou un e-commerce", href: "https://www.francenum.gouv.fr/guides-et-conseils/developpement-commercial/site-web/combien-payer-pour-un-site-web-ou-un-site-e" }] },
    { type: "heading", text: "Ce qui fait varier le devis" },
    { type: "table", caption: "Les postes à comparer à périmètre égal", headers: ["Poste", "Question à poser"], rows: [["Conception", "Une structure et des maquettes spécifiques sont-elles prévues ?"], ["Contenus", "Qui rédige les textes et prépare les photos ?"], ["Fonctions", "Quels formulaires, paiements ou connexions sont compris ?"], ["Mise en ligne", "Quels tests, transferts et réglages sont réalisés ?"], ["Suivi", "Que couvrent l’hébergement, les mises à jour et l’assistance ?"]] },
    { type: "heading", level: 3, text: "Le nombre de pages ne suffit pas" },
    { type: "paragraph", text: "Dix pages utilisant le même modèle peuvent demander moins de conception que trois interfaces particulières. Une boutique ajoute aussi des sujets indépendants du design : fiches produits, livraison, stock, paiement et gestion des commandes. Faites décrire les parcours attendus, et pas seulement le nombre d’écrans." },
    { type: "heading", level: 3, text: "Les contenus ont un coût, même quand vous les fournissez" },
    { type: "paragraph", text: "Choisir les images, vérifier les droits, rédiger les services et relire les pages prend du temps. Si votre équipe s’en charge, ce travail ne disparaît pas du budget global. Une livraison bloquée par des contenus manquants peut aussi retarder la mise en ligne. Précisez qui fournit quoi et à quelle étape." },
    { type: "heading", text: "Calculer le coût total plutôt que le seul lancement" },
    { type: "paragraph", text: "Additionnez le prix initial, les frais annuels et les évolutions prévisibles sur une période choisie. Incluez le domaine, l’hébergement, les licences, la maintenance et les éventuelles commissions de paiement. Demandez également les conditions de sortie : pouvez-vous récupérer les contenus, déplacer le site et conserver le domaine ? Un abonnement peut être adapté, à condition de connaître sa durée et ce qu’il laisse à votre disposition." },
    { type: "paragraph", text: "Exemple de cadrage : un artisan souhaite présenter ses interventions et recevoir des demandes de devis. Il peut commencer par des pages de services claires, des réalisations et un formulaire utile. Un espace client et un configurateur peuvent attendre si personne ne les utilisera au départ. À l’inverse, une boutique doit traiter son parcours d’achat dès la première version." },
    { type: "heading", text: "La checklist avant de demander une estimation" },
    { type: "list", items: ["Décrire l’objectif principal : être contacté, vendre, réserver ou donner accès à un service.", "Lister les parcours indispensables et ceux qui peuvent attendre.", "Faire l’inventaire des textes, photos, produits et accès déjà disponibles.", "Préciser qui mettra le site à jour et avec quel niveau d’autonomie.", "Demander les exclusions, les frais récurrents et les conditions de transfert.", "Comparer les devis sur le même périmètre, avec les montants HT/TTC explicités."] },
    { type: "paragraph", text: "Le bon arbitrage consiste à financer ce qui rend votre première version utile, puis à prévoir son évolution. Réduire le budget en retirant une fonction secondaire est souvent plus raisonnable que supprimer les tests, les contenus ou la préparation du mobile." },
    { type: "links", label: "Préparer votre projet", links: [{ href: "/creation-site", label: "Comprendre notre accompagnement en création de site" }, { href: "/realisations", label: "Observer des réalisations web concrètes" }, { href: "/ressources/refonte-site-internet-quand", label: "Déterminer si une refonte est nécessaire" }] },
  ] }),
  article({ id: "website-redesign", slug: "refonte-site-internet-quand", title: "Refonte de site internet : quand faut-il vraiment la faire ?", description: "Distinguez une refonte nécessaire d’une amélioration ciblée : diagnostic, critères de décision et précautions pour préserver votre site et son référencement.", topic: "web", relatedServices: ["website", "ux-conversion"], relatedResources: ["website-cost-2026", "seo-or-ads"], keywords: ["quand refaire son site internet", "refonte site internet", "audit site web", "refonte ou optimisation"], cta: { type: "contact", label: "Faire le point sur votre site" }, sourceRefs: ["https://developers.google.com/search/docs/crawling-indexing/site-move-with-url-changes?hl=fr"], content: [
    { type: "paragraph", text: "Un site ancien n’a pas forcément besoin d’être remplacé. Un site récent peut déjà empêcher vos visiteurs de comprendre votre offre. La décision doit partir des problèmes observés : informations inexactes, parcours difficiles, outils impossibles à maintenir ou fonctions devenues indispensables. Commencez par identifier ce qui ne fonctionne plus avant de commander un nouveau design." },
    { type: "heading", text: "Les signaux qui justifient un diagnostic" },
    { type: "list", items: ["Votre offre a changé, mais la navigation et les pages présentent encore l’ancienne activité.", "Sur mobile, le contact, la lecture ou une action importante sont difficiles.", "Un formulaire ou un parcours d’achat échoue lors d’un test réel.", "Les mises à jour et les corrections sont bloquées par une base technique devenue difficile à entretenir.", "Les visiteurs ne trouvent pas les informations nécessaires avant de demander un devis."] },
    { type: "paragraph", text: "Une baisse de demandes mérite une enquête, mais elle ne prouve pas à elle seule que le site est en cause. La saison, les campagnes, le suivi des appels ou une modification de l’offre peuvent expliquer le changement. Comparez les sources de visite et les actions réelles plutôt que de conclure à partir d’un compteur global." },
    { type: "heading", text: "Améliorer une partie ou refaire l’ensemble ?" },
    { type: "table", caption: "Choisir une intervention proportionnée", headers: ["Situation", "Premier choix à examiner"], rows: [["Une page de service confuse", "Réécriture et amélioration de cette page"], ["Formulaire trop complexe", "Simplification du parcours et test d’envoi"], ["Images lourdes sur plusieurs pages", "Optimisation des médias et diagnostic de performance"], ["Offre et navigation entièrement dépassées", "Refonte de l’architecture et des contenus"], ["Socle technique bloquant plusieurs fonctions", "Étude de migration et refonte technique"]] },
    { type: "paragraph", text: "Exemple : une entreprise reçoit des visites sur ses pages de prestations, mais le bouton de demande est difficile à repérer. Tester un contact plus visible et un formulaire plus court peut être une première intervention. Si la structure mélange plusieurs métiers et ne permet plus d’ajouter les bonnes pages, une refonte plus large devient pertinente." },
    { type: "heading", text: "Faire un état des lieux avant les maquettes" },
    { type: "heading", level: 3, text: "Tester le site comme un prospect" },
    { type: "paragraph", text: "Sur un téléphone, cherchez une prestation, vérifiez la zone desservie et envoyez une demande test. Faites aussi ce parcours au clavier. Notez les hésitations, les erreurs et les informations manquantes. Demandez à une personne qui connaît peu votre entreprise d’effectuer la même tâche : ses questions peuvent révéler des ambiguïtés que l’équipe ne remarque plus." },
    { type: "heading", level: 3, text: "Conserver ce qui fonctionne" },
    { type: "paragraph", text: "Inventoriez les pages, les contenus utiles, les accès et les intégrations. Lorsque vous disposez de Search Console, repérez les pages qui reçoivent des clics et leurs requêtes. Vérifiez également les demandes qualifiées associées aux principales entrées du site. Le nouveau site doit préserver les réponses utiles, même si leur présentation change." },
    { type: "heading", text: "Protéger les URLs et le référencement pendant la migration" },
    { type: "paragraph", text: "Si des URLs changent, préparez une correspondance vers les nouvelles pages pertinentes et des redirections permanentes. Contrôlez les liens internes, les canonical et le sitemap. Google recommande de suivre la migration et signale que les positions peuvent fluctuer pendant le traitement des changements. Envoyer toutes les anciennes pages vers l’accueil ne remplace pas une correspondance adaptée." },
    { type: "links", label: "Pour organiser une migration", links: [{ href: "https://developers.google.com/search/docs/crawling-indexing/site-move-with-url-changes?hl=fr", label: "Les recommandations de Google sur les changements d’URLs" }] },
    { type: "heading", text: "Le brief minimum d’une refonte utile" },
    { type: "list", items: ["Le problème à résoudre, décrit avec un exemple observable.", "Les pages et fonctions à conserver, corriger ou retirer.", "Le parcours prioritaire et la manière de vérifier qu’il fonctionne.", "Les contenus disponibles et la personne chargée des validations.", "La liste des accès : domaine, hébergement, CMS et outils de mesure.", "Le plan de mise en ligne, de redirections et de contrôle après lancement."] },
    { type: "paragraph", text: "Vous pouvez décider de commencer par une amélioration ciblée et réévaluer ensuite. Si plusieurs limites structurelles se cumulent, cadrer une refonte permet de traiter leurs causes ensemble. Dans les deux cas, fixez des critères de réception concrets : parcours utilisables, contenus exacts, formulaires reçus et anciennes URLs prises en charge." },
    { type: "links", label: "Passer du diagnostic au projet", links: [{ href: "/creation-site", label: "Préparer une création ou une refonte avec CODE-V" }, { href: "/ressources/prix-site-internet-professionnel-2026", label: "Construire le budget d’un site professionnel" }, { href: "/realisations", label: "Découvrir les réalisations" }] },
  ] }),
  article({ id: "seo-or-ads", slug: "seo-ou-google-ads-prospects", title: "SEO ou Google Ads : que choisir pour générer des prospects ?", description: "Comparez SEO et Google Ads selon votre délai, votre budget et votre offre. Une méthode pour choisir un canal et mesurer les demandes réellement utiles.", topic: "acquisition", serviceFamilies: ["acquisition", "seo"], relatedServices: ["seo"], relatedResources: ["ads-budget", "local-google-visibility"], keywords: ["SEO ou Google Ads", "référencement naturel ou payant", "acquisition prospects Google", "SEO SEA différence"], cta: { type: "contact", label: "Choisir votre stratégie d’acquisition" }, sourceRefs: ["https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=fr", "https://support.google.com/google-ads/answer/1722122?hl=fr"], content: [
    { type: "paragraph", text: "Si votre offre est claire et qu’une demande existe sur Google, le SEO et Google Ads peuvent tous deux vous mettre en relation avec des prospects. Le choix dépend surtout du délai disponible, du budget et de la capacité du site à transformer une visite en demande. Avant de répartir vos moyens, définissez ce qu’est un prospect utile : besoin couvert, zone desservie et projet compatible avec votre activité." },
    { type: "heading", text: "Deux moyens différents d’apparaître dans la recherche" },
    { type: "paragraph", text: "Le SEO consiste à améliorer les contenus et le site pour leur visibilité dans les résultats naturels. Google Ads permet de diffuser des annonces dans le cadre d’enchères publicitaires. Acheter des annonces n’achète pas une meilleure position naturelle. Le SEO demande du travail même sans paiement par clic ; Ads implique un budget de diffusion en plus de la préparation et du suivi." },
    { type: "table", caption: "SEO et campagnes Search : comparer les contraintes", headers: ["Critère", "SEO", "Google Ads Search"], rows: [["Démarrage", "Les changements doivent être découverts et évalués", "Diffusion possible après configuration et validation"], ["Dépenses", "Technique, contenus et suivi", "Diffusion, préparation et gestion"], ["Contrôle", "Position et présence non garanties", "Ciblage et budget pilotables, diffusion non garantie"], ["Arrêt du travail", "Des pages peuvent continuer à être visibles", "La diffusion cesse lorsque les campagnes sont arrêtées"], ["Fondation commune", "Une page répondant précisément au besoin", "Une page répondant précisément au besoin"]] },
    { type: "heading", text: "Quand commencer par Google Ads ?" },
    { type: "paragraph", text: "Ads peut être pertinent pour tester une offre précise, accompagner une période commerciale ou chercher des demandes sans attendre que de nouvelles pages gagnent en visibilité naturelle. Il faut toutefois une enveloppe de test supportable et une personne capable de traiter les demandes. Une campagne mal ciblée peut consommer son budget sur des recherches qui ne correspondent pas à vos prestations." },
    { type: "paragraph", text: "Exemple de cadrage : un prestataire intervient sur une zone définie pour une prestation urgente. Une campagne limitée à cette offre et à cette zone peut être étudiée. La page doit indiquer les interventions couvertes et proposer un contact simple. Les termes de recherche et la qualification des appels diront ensuite si le ciblage répond au besoin." },
    { type: "heading", text: "Quand donner la priorité au SEO ?" },
    { type: "paragraph", text: "Le SEO est adapté lorsque vous voulez construire une présence sur des questions récurrentes et disposez du temps nécessaire pour enrichir votre site. Il peut aussi devenir prioritaire si vos pages de services sont difficiles à comprendre ou peu accessibles aux moteurs. Une bonne base profite à la lecture et aux autres canaux, mais ne garantit ni position ni nombre de demandes." },
    { type: "paragraph", text: "Pour une activité locale, la fiche Google et les pages décrivant les services réels peuvent être plus urgentes qu’un grand calendrier d’articles. Pour une offre spécialisée, une page commerciale précise et un guide qui aide à décider peuvent former un ensemble utile. Évitez de produire des dizaines de textes sans lien avec les demandes que vous souhaitez recevoir." },
    { type: "heading", text: "Mesurer la qualité des demandes, pas seulement les clics" },
    { type: "heading", level: 3, text: "Définir les actions à suivre" },
    { type: "paragraph", text: "Distinguez un clic sur un téléphone, un appel abouti, un formulaire reçu et une demande qualifiée. Ils ne racontent pas la même chose. Vérifiez le fonctionnement du suivi et rapprochez-le des demandes effectivement reçues. Si plusieurs canaux interviennent avant le contact, gardez cette limite en tête dans l’attribution." },
    { type: "heading", level: 3, text: "Faire un calcul adapté à votre entreprise" },
    { type: "paragraph", text: "Pour Ads, divisez les dépenses de diffusion par le nombre de demandes qualifiées attribuées à la campagne, puis examinez séparément les frais de gestion. Pour le SEO, observez l’investissement et les demandes sur une période cohérente avec le travail réalisé. Comparez ensuite avec votre marge, votre capacité de traitement et la transformation en clients. Un coût acceptable dépend de votre économie, pas d’un seuil universel." },
    { type: "heading", text: "Décider sans opposer les deux leviers" },
    { type: "list", items: ["Vérifier que la page répond à une offre et une audience précises.", "Choisir un premier périmètre compatible avec vos ressources.", "Définir le délai, le budget et les critères de demande qualifiée.", "Suivre les recherches, les contacts reçus et leurs suites commerciales.", "Corriger le parcours ou le ciblage avant d’augmenter les dépenses."] },
    { type: "links", label: "Approfondir les deux approches", links: [{ href: "/referencement", label: "Notre approche du référencement naturel" }, { href: "/publicite", label: "Préparer une campagne publicitaire" }, { href: "/ressources/visibilite-locale-google", label: "Améliorer sa présence locale sur Google" }, { href: "/realisations", label: "Voir des exemples de sites réalisés" }, { href: "https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=fr", label: "Google : les fondamentaux du SEO" }, { href: "https://support.google.com/google-ads/answer/1722122?hl=fr", label: "Google Ads : le fonctionnement du classement des annonces" }] },
  ] }),
  article({ id: "local-google-visibility", slug: "visibilite-locale-google", title: "Comment améliorer sa visibilité locale sur Google ?", description: "Fiche Google, pages de services, avis et suivi des demandes : les actions prioritaires pour rendre une entreprise locale plus facile à trouver et à contacter.", topic: "seo", searchIntent: "informational", relatedServices: ["local-seo", "gbp-management"], relatedResources: ["gbp-optimization", "seo-or-ads"], keywords: ["améliorer visibilité locale Google", "référencement local", "optimiser fiche Google", "Google Business Profile"], cta: { type: "contact", label: "Parler de votre visibilité locale" }, sourceRefs: ["https://support.google.com/business/answer/7091/improve-your-local-ranking-on-google?hl=en-GB", "https://support.google.com/business/answer/3038177?hl=fr"], content: [
    { type: "paragraph", text: "Une personne qui cherche une entreprise près de chez elle veut savoir si vous proposez le bon service, si vous intervenez dans sa zone et comment vous joindre. Votre présence locale doit rendre ces réponses faciles à trouver. Commencez par votre fiche Google et les pages utiles de votre site, puis organisez leur mise à jour et le suivi des demandes." },
    { type: "heading", text: "Comprendre ce que vous pouvez réellement améliorer" },
    { type: "paragraph", text: "Google décrit trois grands facteurs pour les résultats locaux : la pertinence, la distance et la notoriété. Des informations précises aident à représenter votre activité ; la position du chercheur reste une contrainte. Une optimisation de fiche ne permet donc pas de choisir librement son classement dans toutes les villes. Google précise qu’il n’est pas possible de payer pour un meilleur classement local naturel." },
    { type: "heading", text: "Commencer par une fiche exacte et maîtrisée" },
    { type: "list", items: ["Vérifier que vous avez accès à la bonne fiche et que l’établissement est validé.", "Utiliser le nom réel de l’entreprise, sans ajouter une suite de mots-clés.", "Choisir une catégorie principale qui décrit l’activité, puis seulement les catégories complémentaires pertinentes.", "Vérifier le téléphone, le site, les horaires et les horaires exceptionnels.", "Renseigner l’adresse ou la zone desservie selon la façon dont vous accueillez ou rejoignez les clients.", "Ajouter des photos réelles et actuelles qui aident à comprendre vos locaux ou votre travail."] },
    { type: "paragraph", text: "Les consignes Google concernent notamment les établissements qui accueillent des clients ou interviennent chez eux. Une activité uniquement en ligne n’a pas automatiquement droit à une fiche. Avant de créer un nouvel établissement ou de modifier une adresse, vérifiez les règles applicables. Une seconde fiche créée pour la même activité peut compliquer la gestion au lieu d’améliorer la visibilité." },
    { type: "heading", text: "Faire travailler le site et la fiche ensemble" },
    { type: "heading", level: 3, text: "Une page pour répondre à un besoin réel" },
    { type: "paragraph", text: "Décrivez les prestations, les conditions d’intervention et les moyens de contact. Pour un artisan, une page peut expliquer les situations prises en charge, la zone réelle et les éléments à transmettre pour obtenir une estimation. Des photos de réalisations rendent le travail observable. Le site apporte le détail que la fiche ne peut pas contenir." },
    { type: "heading", level: 3, text: "Des pages locales seulement lorsqu’elles sont utiles" },
    { type: "paragraph", text: "Créer une page par ville en changeant seulement le nom du lieu n’apporte pas une réponse différente au lecteur. Une page locale se justifie mieux par un établissement, des modalités d’intervention particulières ou des informations concrètes propres à la zone. Si votre fonctionnement est identique partout, une page de zone desservie bien écrite peut suffire." },
    { type: "heading", text: "Organiser les avis et les réponses" },
    { type: "paragraph", text: "Proposez aux clients de partager leur expérience sans dicter le texte ni acheter leur avis. Répondez de manière utile et gardez les détails personnels hors de la réponse publique. Les avis aident surtout un lecteur à évaluer une entreprise. Traitez également ce qu’ils révèlent : un problème de prise de rendez-vous ou de compréhension de la prestation mérite une correction dans le parcours." },
    { type: "heading", text: "Un plan d’action simple pour votre prochaine mise à jour" },
    { type: "table", caption: "Prioriser le travail local", headers: ["Priorité", "Action", "Vérification"], rows: [["Informations", "Corriger fiche et coordonnées du site", "Téléphone et horaires exacts"], ["Offre", "Clarifier les pages de services", "Service et zone compris sans appeler"], ["Contact", "Tester appel et formulaire sur mobile", "Une demande test arrive correctement"], ["Confiance", "Ajouter des photos et organiser les avis", "Contenus représentatifs de l’activité"], ["Suivi", "Examiner demandes et recherches disponibles", "Qualifier les contacts réellement reçus"]] },
    { type: "paragraph", text: "Exemple : une entreprise affiche des horaires différents entre sa fiche et son site. Les corriger ne demande pas une refonte, mais enlève une source d’hésitation. Si la fiche dirige vers une page d’accueil vague, compléter une page de service peut constituer l’étape suivante. Cette démarche privilégie les obstacles concrets avant les actions plus longues." },
    { type: "paragraph", text: "Suivez les informations disponibles dans votre fiche et Search Console, puis confrontez-les aux appels et aux demandes. Vérifiez leur zone et leur adéquation avec l’offre. Une évolution de visibilité seule ne dit pas si les contacts sont utiles. Conservez les dates de vos modifications pour mieux interpréter les changements, sans attribuer automatiquement chaque variation à la dernière action." },
    { type: "links", label: "Poursuivre sur la visibilité locale", links: [{ href: "/referencement-local", label: "Construire votre présence locale avec CODE-V" }, { href: "/ressources/seo-ou-google-ads-prospects", label: "Choisir entre SEO et Google Ads" }, { href: "/realisations", label: "Voir comment des activités locales sont présentées sur le web" }, { href: "https://support.google.com/business/answer/7091/improve-your-local-ranking-on-google?hl=en-GB", label: "Google : les facteurs du classement local" }, { href: "https://support.google.com/business/answer/3038177?hl=fr", label: "Google : les règles de représentation d’un établissement" }] },
  ] }),
  article({ id: "first-automations", slug: "taches-automatiser-petite-entreprise", title: "Quelles tâches automatiser en premier dans une petite entreprise ?", description: "Repérez les tâches répétitives à automatiser, comparez leur intérêt et leurs risques, puis testez un premier flux simple sans perdre le contrôle de vos opérations.", topic: "automation", searchIntent: "informational", relatedServices: ["business-workflows", "api-integrations"], relatedResources: ["useful-ai-agents"], keywords: ["tâches automatiser petite entreprise", "automatisation TPE PME", "première automatisation", "automatiser tâches administratives"], cta: { type: "contact", label: "Identifier ce que vous pouvez automatiser" }, sourceRefs: ["https://www.francenum.gouv.fr/guides-et-conseils/pilotage-de-lentreprise/numerisation-des-processus"], content: [
    { type: "paragraph", text: "La meilleure première automatisation est souvent une tâche peu spectaculaire : recopier une demande, créer un dossier ou prévenir la bonne personne. Elle se répète, suit des règles claires et peut être vérifiée facilement. Commencez par un flux que votre équipe comprend déjà, plutôt que par un agent censé gérer tout le fonctionnement de l’entreprise." },
    { type: "heading", text: "Observer avant de choisir un outil" },
    { type: "paragraph", text: "Pendant une période représentative de votre activité, notez les tâches répétées, les outils concernés et les erreurs rencontrées. Mesurez le temps réel quand c’est possible. Distinguez le travail administratif du jugement métier : copier une référence et accepter un devis ne demandent pas le même niveau de contrôle. Un processus flou doit d’abord être clarifié." },
    { type: "heading", text: "Cinq points de départ possibles" },
    { type: "table", caption: "Des flux simples à examiner selon votre fonctionnement", headers: ["Tâche", "Automatisation possible", "Contrôle à conserver"], rows: [["Demandes entrantes", "Créer une fiche dans le CRM et notifier un responsable", "Vérifier les doublons et les champs obligatoires"], ["Classement", "Créer un dossier et y ranger les documents reçus", "Gérer les droits et les fichiers mal nommés"], ["Suivi interne", "Rappeler une échéance à l’équipe", "Ne pas déclencher une action client sans validation"], ["Tableaux de bord", "Regrouper des données issues des outils", "Contrôler la source et la date des données"], ["Préparation d’emails", "Préremplir un message à partir d’un dossier", "Relire avant un envoi engageant"]] },
    { type: "paragraph", text: "Ces cas d’usage sont des pistes, pas une obligation de tout connecter. Si votre outil possède déjà une fonction native adaptée, commencez par l’examiner. Ajouter un service externe n’est utile que s’il résout un manque et si quelqu’un peut entretenir le lien entre les outils." },
    { type: "heading", text: "Choisir un flux dont le bénéfice peut être observé" },
    { type: "list", items: ["La tâche se répète assez souvent pour justifier sa préparation et son entretien.", "Les étapes et les règles sont connues, y compris les exceptions courantes.", "Les données arrivent dans un format suffisamment stable.", "Les outils permettent une connexion autorisée ou un export exploitable.", "Une personne sait vérifier le résultat et intervenir en cas d’échec.", "Une erreur peut être détectée et corrigée sans conséquence disproportionnée."] },
    { type: "paragraph", text: "Pour estimer l’intérêt, partez de vos propres mesures : fréquence multipliée par temps consacré, puis retirez le temps de contrôle et de gestion des exceptions. Comparez ce gain possible au coût de mise en place, aux abonnements et à la maintenance. Un flux rare mais critique peut mériter un traitement pour sa fiabilité ; un flux fréquent mais très variable peut rester coûteux à automatiser." },
    { type: "heading", text: "Exemple : du formulaire au suivi commercial" },
    { type: "paragraph", text: "Une petite équipe reçoit une demande via son site. Le flux vérifie les champs, crée ou met à jour une fiche, assigne un responsable et envoie une notification interne. Le responsable conserve la qualification et la réponse commerciale. Si une fiche existe déjà, une règle évite de la dupliquer ; si le CRM ne répond pas, une alerte permet de reprendre la demande. Le scénario doit être testé avec des données de test avant son usage réel." },
    { type: "heading", text: "Automatisation et IA : deux besoins à distinguer" },
    { type: "heading", level: 3, text: "Une règle suffit quand la décision est explicite" },
    { type: "paragraph", text: "Créer un dossier après validation ou transmettre un formulaire complet ne nécessite pas forcément d’IA. Une règle explicite est plus facile à vérifier. Gardez une trace des événements, prévoyez un moyen d’arrêter le flux et évitez qu’une nouvelle tentative crée plusieurs fois la même action." },
    { type: "heading", level: 3, text: "L’IA peut préparer un travail à relire" },
    { type: "paragraph", text: "Résumer un message libre ou proposer une catégorie peut aider, mais une sortie plausible peut être incorrecte. Prévoyez une validation pour les décisions engageantes. Avant de transmettre des données, examinez leur sensibilité, les accès et les conditions du service choisi. Ne donnez au flux que les informations et permissions nécessaires." },
    { type: "heading", text: "Tester petit, puis décider de la suite" },
    { type: "paragraph", text: "Documentez le déclencheur, les étapes, le résultat attendu et le responsable. Testez un doublon, un champ manquant, une panne d’outil et une annulation. Vérifiez les résultats en parallèle du processus habituel, puis mesurez le temps réellement économisé. Étendez le flux seulement lorsque les exceptions sont comprises et que l’équipe sait reprendre la main." },
    { type: "links", label: "Du cas d’usage au premier flux", links: [{ href: "/solutions/automatisation-ia", label: "Explorer l’automatisation et l’IA avec CODE-V" }, { href: "/realisations", label: "Découvrir les productions CODE-V" }, { href: "/contact", label: "Décrire votre tâche répétitive" }, { href: "https://www.francenum.gouv.fr/guides-et-conseils/pilotage-de-lentreprise/numerisation-des-processus", label: "France Num : la numérisation des processus" }] },
  ] }),
  draft({ id: "website-brief", slug: "preparer-refonte-site", title: "Préparer une refonte de site", description: "Guide prévu : préciser le besoin, les contenus et les contraintes avant de choisir une solution.",
    format: "guide", topic: "web", relatedServices: ["website", "ux-conversion"], relatedProjects: [], relatedResources: ["local-visibility-brief"], keywords: ["préparer refonte site"], searchIntent: "commercial", funnelStage: "consideration", cta: { type: "solution", family: "web", label: "Explorer Web & Applications" } }),
  draft({ id: "local-visibility-brief", slug: "site-ou-fiche-google", title: "Site web ou fiche Google : quel rôle pour chacun ?", description: "Comparatif prévu : distinguer la présentation de l’activité et sa présence dans les recherches locales.",
    format: "comparison", topic: "seo", relatedServices: ["website", "local-seo", "gbp-management"], relatedProjects: [], relatedResources: ["website-brief"], keywords: ["site web fiche Google"], searchIntent: "informational", funnelStage: "discovery", cta: { type: "solution", family: "seo", label: "Comprendre la visibilité locale" } }),
  draft({ id: "automation-brief", slug: "choisir-premiere-automatisation", title: "Choisir sa première automatisation", description: "Checklist prévue : repérer une tâche répétitive et vérifier les données, outils et responsabilités nécessaires.",
    format: "checklist", topic: "automation", relatedServices: ["business-workflows", "api-integrations"], relatedProjects: ["code-v-motion"], relatedResources: [], keywords: ["première automatisation entreprise"], searchIntent: "commercial", funnelStage: "consideration", cta: { type: "chat", intent: "automation", label: "Décrire la tâche à automatiser" } }),
];

export function isPublishedResource(resource: Resource): boolean {
  return resource.status === "published" && Boolean(
    resource.content?.length && resource.content.every(block => block.type === "list" ? block.items.length > 0 && block.items.every(item => item.trim()) : block.type === "links" ? block.label.trim() && block.links.length > 0 && block.links.every(link => link.label.trim() && (/^\/(?!\/)/.test(link.href) || /^https:\/\//.test(link.href))) : block.type === "table" ? block.caption.trim() && block.headers.length > 0 && block.headers.every(cell => cell.trim()) && block.rows.length > 0 && block.rows.every(row => row.length === block.headers.length && row.every(cell => cell.trim())) : block.text.trim()) &&
    resource.publishedAt && /^\d{4}-\d{2}-\d{2}/.test(resource.publishedAt) && Number.isFinite(Date.parse(resource.publishedAt)) && Date.parse(resource.publishedAt) <= Date.now() &&
    (!resource.updatedAt || Number.isFinite(Date.parse(resource.updatedAt)) && Date.parse(resource.updatedAt) >= Date.parse(resource.publishedAt)) &&
    resource.author?.name.trim() && resource.sourceRefs.length && resource.sourceRefs.every(source => source.trim())
  );
}
export function getPublishedResources() { return resources.filter(isPublishedResource); }
/** Articles share the existing publication gate and canonical detail route. */
export function getPublishedArticles() {
  return getPublishedResources().filter(resource => resource.format === "article")
    .sort((a, b) => Date.parse(b.publishedAt!) - Date.parse(a.publishedAt!));
}
/** Public lookup deliberately excludes drafts, even when a slug is known. */
export function getPublishedResourceBySlug(slug: string) { return getPublishedResources().find(resource => resource.slug === slug); }
export function getResourcesByServiceFamily(family: ServiceCategory) { return getPublishedResources().filter(resource => resource.serviceFamilies.includes(family)); }
export function getResourcesByProject(projectId: string) { return getPublishedResources().filter(resource => resource.relatedProjects.includes(projectId)); }
export function getResourcesByService(service: ServiceId) { return getPublishedResources().filter(resource => resource.relatedServices.includes(service)); }
export function getRelatedResources(resource: Resource) { return getPublishedResources().filter(other => resource.relatedResources.includes(other.id)); }
export function getRelatedSolutions(resource: Resource) { return solutionNavigation.filter(solution => resource.serviceFamilies.includes(solution.id)); }
export function getRelatedProjects(resource: Resource) { return projects.filter(project => resource.relatedProjects.includes(project.id) && project.status === "published"); }

export function getResourceCtaHref(cta: ResourceCta): string | null {
  switch (cta.type) {
    case "solution": return solutionNavigation.find(solution => solution.id === cta.family)?.href ?? null;
    case "project": {
      const project = projects.find(item => item.id === cta.projectId);
      if (!project || project.status !== "published") return null;
      return `/realisations#${project.kind === "internal" ? "laboratoire" : project.featured ? "selection" : project.slug}`;
    }
    case "audit": return `/contact?service=${encodeURIComponent(cta.service)}`;
    case "explain-project": case "contact": return "/contact";
    case "chat": return null;
  }
}

/** Existing proof/media for the hub, independent of unpublished editorial briefs. */
export const resourceHubProject = getPublishedProjects().find(project => project.slug === "chateau-de-projan");
export const resourceHubVideo = getPublishedProjects().find(project => project.slug === "code-v-motion")?.video ?? null;
